import{_ as e,o as t,c as i,a5 as o}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"协作权限与身份验证","description":"","frontmatter":{"title":"协作权限与身份验证","docId":"developer.collaboration","translationKey":"developer.collaboration","locale":"zh","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"fb71673a581e923e3c02ae401a46937b007f9919690ca020d22c27b370b6c61d","translationRevision":"c13d4e37e61a1a45537a43ba8304c2eeb1beae2e49d36651785d6059977939a5","order":190},"headers":[],"relativePath":"zh/developer/collaboration.md","filePath":"zh/developer/collaboration.md","lastUpdated":1794611623000}'),s={name:"zh/developer/collaboration.md"};function r(l,a,n,h,d,c){return t(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="collaboration-authority-and-authentication" tabindex="-1">协作权限与身份验证 <a class="header-anchor" href="#collaboration-authority-and-authentication" aria-label="Permalink to &quot;协作权限与身份验证 {#collaboration-authority-and-authentication}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>允许获批准的设备查看现有宿主，或在其上执行范围有限的操作。使用测试所有者配置、支持远程的构建及已配置传输。账户登录、Cloud 团队成员身份、本地所有权和直接委托会话是不同的权限来源。</p><h2 id="establish-the-trust-chain" tabindex="-1">建立信任链 <a class="header-anchor" href="#establish-the-trust-chain" aria-label="Permalink to &quot;建立信任链 {#establish-the-trust-chain}&quot;">​</a></h2><p>本地所有者的 <code>collaboration.*</code> 管理负责配置、邀请、待处理请求、主体、授权、会话及审计。配置监听器或创建凭据前，先发现 schema：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.configure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.invites.create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> collaboration.status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span></span></code></pre></div><p>邀请启动配对，本身不授予业务权限。所有者批准后才创建对应会话/授权。直接 HTTPS 需要经过验证的证书，或明确固定的原生信任。原生 bearer 与浏览器 Cookie 的边界不同。初始 <code>collaboration.hello</code> 绑定协议、宿主实例、主体、会话、授权修订、能力及协商限制。</p><h2 id="authorize-each-operation" tabindex="-1">逐项授权操作 <a class="header-anchor" href="#authorize-each-operation" aria-label="Permalink to &quot;逐项授权操作 {#authorize-each-operation}&quot;">​</a></h2><p>支持的远程方法必须通过允许列表、能力、资源限制及当前会话检查。工作流程禁用/删除使用持久化比较并交换元数据。积分调整具有累加性质，并有独立授权限制。远程自动化读取只返回封闭式摘要；禁用且归作者所有的草稿，不会仅因保存就获得可执行的所有者权限。</p><p>所有者审查/采纳及经过检查的批准，会绑定当前定义、依赖及来源。预览清单报告的是检查数据，不是执行令牌。应在执行边界重新验证授权和资源绑定，不能把传输身份当成永久权限。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>直接原生协作已实现限定范围读取、部分持久化修改及有界恢复。Cloud 团队/中继另有各自适配器；文档中的 Cloud 中继读取路径不能被描述为完整管理或草稿执行。其余委托效果、领域写入和多电脑验收仍属实验性。选定路径见<a href="./remote-client.html">远程客户端</a>和 <a href="./cloud.html">Cloud</a>。</p><h2 id="recover-and-verify" tabindex="-1">恢复与验证 <a class="header-anchor" href="#recover-and-verify" aria-label="Permalink to &quot;恢复与验证 {#recover-and-verify}&quot;">​</a></h2><p>撤销或身份改变时，停止订阅并丢弃私有投影。按协商领域和游标有效性使用 <code>collaboration.subscribe</code>、<code>snapshot</code> 和 <code>resume</code>。确认不确定时，查询原始命令 ID。不要换新 ID 重试删除，也不要根据旧回执恢复权限。<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-collaboration/src" target="_blank" rel="noreferrer">授权源码</a>和注册表策略定义边界；仅通过 TLS 不是授权测试。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>Teams 流程：注册设备、发出/加入邀请或访问请求、批准，再由宿主确认原生权限的当前修订。<code>pendingHost</code> 表示最后一步未完成。新修订使旧确认失效；expectedRevision 过期时重新加载。原生接收要求新快照、活动宿主/设备、有效权限且 confirmedRevision 等于 revision。UI 提供宿主/加入面板及可用批准入口；原生确认是 API 契约，不保证所有构建都有相应按钮。</p><p>旧角色映射为封闭集合：observer 获得 live/workflows/积分/竞赛/自动化/结果读取；moderator 额外获得积分调整、workflow/自动化开关及竞赛管理；automationEditor 在读取外增加自动化编辑。预设不授予任意脚本、外部副作用或可复用自动化委派。显式 <code>nativeGrant</code> 要求 <code>custom</code>，并在那里限制资源、副作用范围和积分 delta。原生客户端只支持 <code>desktop</code> 或 <code>agent</code>。不支持的策略直接失败，不会扩大权限。分别诊断配对、宿主确认、修订新鲜度和传输。</p>`,17)])])}const u=e(s,[["render",r]]);export{k as __pageData,u as default};
